script:
frappe.ui.form.on('Enrollment', {
    refresh: function(frm) {
        calculate_final_fee(frm);

        if (!frm.is_new()) {
            frm.add_custom_button(__('Tạo Phiếu Thu'), function() {
                frappe.model.with_doctype('Student Payment Entry', function() {
                    let payment = frappe.model.get_new_doc('Student Payment Entry');
                    payment.student_id = frm.doc.student_id;
                    payment.enrollment_id = frm.doc.name;
                    payment.payment_type = 'Học phí đầu khóa';
                    payment.amount = frm.doc.final_fee_amount || 0;
                    payment.payment_date = frappe.datetime.get_today();
                    payment.payment_status = 'Đã thanh toán đủ';
                    frappe.set_route('Form', 'Student Payment Entry', payment.name);
                });
            }, __('Tạo mới'));
        }
    },
    class_id: function(frm) {
        calculate_final_fee(frm);
    },
    discount_ammount: function(frm) {
        calculate_final_fee(frm);
    },
    discount_amount: function(frm) {
        calculate_final_fee(frm);
    }
});

function calculate_final_fee(frm) {
    if (!frm.doc.class_id) return;

    frappe.db.get_value('Class', frm.doc.class_id, 'level_id', (r) => {
        let target_level = (r && r.level_id) ? r.level_id : frm.doc.class_id;

        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'Fee Structure',
                filters: { 'level_id': target_level },
                fields: ['base_fee_amount']
            },
            callback: function(res) {
                let base_fee = 0;
                if (res.message && res.message.length > 0) {
                    base_fee = res.message[0].base_fee_amount || 0;
                }

                let discount = (frm.doc.discount_ammount !== undefined) ? frm.doc.discount_ammount : (frm.doc.discount_amount || 0);
                let final_fee = base_fee - discount;
                if (final_fee < 0) final_fee = 0;

                frm.set_value('final_fee_amount', final_fee);
            }
        });
    });
}

frappe.ui.form.on('Teacher Leave Request', {
    onload: function(frm) {
        // Nếu là tạo đơn mới và ô Giáo viên chưa có tên
        if (frm.is_new() && !frm.doc.teacher_id) {
            // Tự tìm mã Giáo viên tương ứng với Email tài khoản đang đăng nhập
            frappe.db.get_value('Teacher', {'email': frappe.session.user}, 'name', function(r) {
                if (r && r.name) {
                    frm.set_value('teacher_id', r.name);
                }
            });
        }
    }
});

frappe.ui.form.on('Student', {
    refresh: function(frm) {
        if (!frm.is_new() && frm.doc.email) {
            frm.add_custom_button(__('Create User Account'), function() {
                let init_password = 'Ling@123456';
                frappe.call({
                    method: 'frappe.client.insert',
                    args: {
                        doc: {
                            doctype: 'User',
                            email: frm.doc.email,
                            first_name: frm.doc.full_name || frm.doc.name,
                            user_type: 'Website User',
                            send_welcome_email: 0,
                            new_password: init_password,
                            roles: [
                                { role: 'Học viên' }
                            ]
                        }
                    },
                    callback: function(r) {
                        if (!r.exc) {
                            // Automatically insert User Permission for Student
                            frappe.call({
                                method: 'frappe.client.insert',
                                args: {
                                    doc: {
                                        doctype: 'User Permission',
                                        user: frm.doc.email,
                                        allow: 'Student',
                                        for_value: frm.doc.name
                                    }
                                }
                            });
                            // Check if student is enrolled in a class and insert User Permission for Class
                            frappe.db.get_list('Enrollment', {
                                filters: { 'student_id': frm.doc.name },
                                fields: ['class_id']
                            }).then(en_records => {
                                if (en_records && en_records.length > 0) {
                                    frappe.call({
                                        method: 'frappe.client.insert',
                                        args: {
                                            doc: {
                                                doctype: 'User Permission',
                                                user: frm.doc.email,
                                                allow: 'Class',
                                                for_value: en_records[0].class_id,
                                                apply_to_all_doctypes: 0,
                                                applicable_for: 'Class'
                                            }
                                        }
                                    });
                                }
                            });
                            frappe.msgprint({
                                title: __('Tạo Tài Khoản Thành Công'),
                                indicator: 'green',
                                message: __('<b>Đã tạo tài khoản & Gắn phân quyền cho Học viên!</b><br><br><b>Email:</b> ') + frm.doc.email + __(' <br><b>Mật khẩu khởi tạo:</b> <code>Ling@123456</code><br><br><i>⚠️ LƯU Ý: Nhắc học viên đổi mật khẩu mới ngay trong lần đăng nhập đầu tiên!</i>')
                            });
                        }
                    }
                });
            }, __('Actions'));
        }
    }
});

frappe.ui.form.on('Guardian', {
    refresh: function(frm) {
        if (!frm.is_new() && (frm.doc.email || frm.doc.phone)) {
            frm.add_custom_button(__('Create User Account'), function() {
                let init_password = 'Ling@123456';
                let clean_phone = frm.doc.phone ? frm.doc.phone.replace(/[^0-9]/g, '') : '';
                let user_email = frm.doc.email || (clean_phone + '@phone.ling');

                if (!clean_phone && !frm.doc.email) {
                    frappe.msgprint(__('Vui lòng nhập Email hoặc Số điện thoại cho Phụ huynh trước!'));
                    return;
                }

                frappe.call({
                    method: 'frappe.client.insert',
                    args: {
                        doc: {
                            doctype: 'User',
                            email: user_email,
                            username: clean_phone || undefined,
                            mobile_no: clean_phone || undefined,
                            first_name: frm.doc.full_name || frm.doc.name,
                            user_type: 'Website User',
                            send_welcome_email: 0,
                            new_password: init_password,
                            roles: [
                                { role: 'Phụ huynh' }
                            ]
                        }
                    },
                    callback: function(r) {
                        if (!r.exc) {
                            let login_id = clean_phone || user_email;
                            frappe.msgprint({
                                title: __('Tạo Tài Khoản Phụ Huynh Thành Công'),
                                indicator: 'green',
                                message: __('<b>Đã tạo tài khoản Phụ huynh thành công!</b><br><br><b>Tên đăng nhập (SĐT):</b> <code>') + login_id + __('</code><br><b>Mật khẩu khởi tạo:</b> <code>Ling@123456</code><br><br><i>💡 Phụ huynh chỉ cần gõ đúng Số điện thoại: <b>') + login_id + __('</b> để đăng nhập!</i>')
                            });
                        }
                    }
                });
            }, __('Actions'));
        }
    }
});

frappe.ui.form.on('Level Transfer', {
    student_id: function(frm) {
        if (frm.doc.student_id) {
            frappe.db.get_doc('Student', frm.doc.student_id).then(student => {
                if (student.current_level_id) {
                    frm.set_value('current_level_id', student.current_level_id);
                }
            });
            frappe.db.get_list('Enrollment', {
                filters: {
                    'student_id': frm.doc.student_id
                },
                fields: ['class_id']
            }).then(records => {
                if (records && records.length > 0) {
                    frm.set_value('current_class_id', records[0].class_id);
                }
            });
        }
    }
});

frappe.listview_settings['Course Schedule'] = {
	onload: function(listview) {
		if (frappe.user.has_role('Giáo viên') && !frappe.user.has_role('Quản lý')) {
			frappe.db.get_value('Teacher', {'email': frappe.session.user}, 'name').then(r => {
				if (r && r.message && r.message.name) {
					listview.filter_area.add([[ 'Course Schedule', 'teacher_id', '=', r.message.name ]]);
				}
			});
		}
	}
};

frappe.ui.form.on('Course Schedule', {
	refresh: function(frm) {
		let can_mark_attendance = frappe.user.has_role('Giáo viên') || frappe.user.has_role('Quản lý') || frappe.user.has_role('System Manager');

		if (!frm.is_new() && frm.doc.class_id && can_mark_attendance) {
			frm.add_custom_button(__('📝 Điểm danh lớp'), function() {
				frappe.call({
					method: 'ling_ielts_erp.course_schedule_handler.get_class_students_for_attendance',
					args: { schedule_id: frm.doc.name },
					freeze: true,
					freeze_message: __('Đang tải danh sách học viên...'),
					callback: function(r) {
						if (r.message && r.message.length > 0) {
							show_batch_attendance_dialog(frm, r.message);
						} else {
							frappe.msgprint(__('Không tìm thấy học viên nào đang học trong lớp ') + frm.doc.class_id);
						}
					}
				});
			}).addClass('btn-primary');
		}
	}
});

function show_batch_attendance_dialog(frm, students) {
	let rows_html = '';
	students.forEach((s, idx) => {
		rows_html += `
			<tr>
				<td style="text-align: center; vertical-align: middle;">${idx + 1}</td>
				<td style="vertical-align: middle;"><b>${s.student_id}</b></td>
				<td style="vertical-align: middle;">${s.full_name}</td>
				<td style="vertical-align: middle;">
					<select class="form-control att-select" data-student-id="${s.student_id}">
						<option value="Có mặt" ${s.attendance_status === 'Có mặt' ? 'selected' : ''}>✅ Có mặt</option>
						<option value="Vắng mặt" ${s.attendance_status === 'Vắng mặt' ? 'selected' : ''}>❌ Vắng mặt</option>
						<option value="Vắng có phép" ${s.attendance_status === 'Vắng có phép' ? 'selected' : ''}>📩 Vắng có phép</option>
					</select>
				</td>
			</tr>
		`;
	});

	let dialog_content = `
		<div style="margin-bottom: 12px; display: flex; justify-content: space-between; align-items: center; background: #f8f9fa; padding: 10px; border-radius: 6px;">
			<span><b>Lớp:</b> ${frm.doc.class_id} &nbsp;|&nbsp; <b>Ngày dạy:</b> ${frm.doc.session_date || ''}</span>
			<button class="btn btn-xs btn-outline-secondary" id="btn-mark-all-present">Tất cả Có mặt</button>
		</div>
		<div style="max-height: 400px; overflow-y: auto;">
			<table class="table table-bordered table-hover" style="margin-bottom: 0;">
				<thead>
					<tr style="background-color: #eef2f7;">
						<th style="width: 50px; text-align: center;">STT</th>
						<th style="width: 140px;">Mã Học viên</th>
						<th>Tên Học viên</th>
						<th style="width: 170px;">Điểm danh</th>
					</tr>
				</thead>
				<tbody>
					${rows_html}
				</tbody>
			</table>
		</div>
	`;

	let d = new frappe.ui.Dialog({
		title: __('📝 Điểm danh nhanh theo Lớp'),
		fields: [
			{
				fieldname: 'attendance_html',
				fieldtype: 'HTML',
				options: dialog_content
			}
		],
		size: 'large',
		primary_action_label: __('Lưu điểm danh'),
		primary_action: function() {
			let data = [];
			d.$wrapper.find('.att-select').each(function() {
				let st_id = $(this).attr('data-student-id');
				let status = $(this).val();
				data.push({
					student_id: st_id,
					schedule_id: frm.doc.name,
					attendance_status: status
				});
			});

			frappe.call({
				method: 'ling_ielts_erp.course_schedule_handler.mark_batch_attendance',
				args: { attendance_data: data },
				freeze: true,
				freeze_message: __('Đang lưu dữ liệu điểm danh...'),
				callback: function(res) {
					if (res.message) {
						frappe.show_alert({ message: __('Đã lưu điểm danh thành công!'), indicator: 'green' });
						d.hide();
						frm.reload_doc();
					}
				}
			});
		}
	});

	d.show();

	d.$wrapper.find('#btn-mark-all-present').on('click', function(e) {
		e.preventDefault();
		d.$wrapper.find('.att-select').val('Có mặt');
	});
}

frappe.ui.form.on('Course Schedule', {
	refresh: function(frm) {
		// Tạo nút "Điểm danh lớp" ở góc trên bên phải thanh công cụ
		if (!frm.is_new() && frm.doc.class_id) {
			frm.add_custom_button(__('Điểm danh lớp'), function() {
				frappe.call({
					method: 'ling_ielts_erp.course_schedule_handler.get_class_students_for_attendance',
